-- =====================================================================
-- JDK Learning System: complete Supabase setup (generated by scripts/build-sql.mjs)
-- Paste into the Supabase SQL Editor and run once, top to bottom.
-- Safe to re-run. Never put the service_role key in frontend code.
-- Edit content in src/data, then run "npm run build:sql" to regenerate this file.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. HELPER FUNCTIONS
-- ---------------------------------------------------------------------

-- Keeps updated_at current on every UPDATE.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------
-- 2. TABLES
-- Composite natural keys are used on child tables (attempt_id + question_id and so on)
-- so uploads from an offline device are idempotent and can never duplicate rows.
-- ---------------------------------------------------------------------

-- Profile row per account. Role is 'learner' for everyone at signup; promote admins in SQL.
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text check (display_name is null or char_length(btrim(display_name)) between 1 and 60),
  role text not null default 'learner' check (role in ('learner', 'admin')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Course content (readable by learners, writable by admins only).
create table if not exists public.courses (
  id text primary key,
  title text not null check (char_length(title) > 0),
  description text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.lessons (
  id text primary key,
  course_id text not null references public.courses(id) on delete cascade,
  title text not null check (char_length(title) > 0),
  position int not null check (position > 0),
  -- null for modules of file-based courses, which are not tied to one competency
  focus_competency smallint check (focus_competency is null or focus_competency between 0 and 3),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.questions (
  id text primary key,
  lesson_id text not null references public.lessons(id) on delete cascade,
  kind text not null check (kind in ('diagnostic', 'lesson', 'module')),
  competency smallint not null check (competency between 0 and 3),
  difficulty smallint not null check (difficulty between 1 and 3),
  question_text text not null check (char_length(question_text) > 0),
  options jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) >= 2),
  correct_index smallint not null check (correct_index >= 0),
  explanation text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Attempt ids are created on the device (uuid) so offline submissions upload later without duplicates.
create table if not exists public.assessment_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id text not null references public.courses(id) on delete restrict,
  lesson_id text references public.lessons(id) on delete restrict,
  kind text not null check (kind in ('diagnostic', 'lesson', 'module')),
  level text check (level is null or level in ('foundational', 'standard', 'advanced')),
  total_answered int not null default 0 check (total_answered >= 0),
  total_correct int not null default 0 check (total_correct >= 0 and total_correct <= total_answered),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((kind = 'diagnostic' and lesson_id is null) or (kind in ('lesson', 'module') and lesson_id is not null))
);

create table if not exists public.assessment_answers (
  attempt_id uuid not null references public.assessment_attempts(id) on delete cascade,
  question_id text not null references public.questions(id) on delete restrict,
  user_id uuid not null references auth.users(id) on delete cascade,
  selected_index smallint check (selected_index is null or selected_index >= 0),
  is_correct boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (attempt_id, question_id)
);

create table if not exists public.competency_results (
  attempt_id uuid not null references public.assessment_attempts(id) on delete cascade,
  competency smallint not null check (competency between 0 and 3),
  user_id uuid not null references auth.users(id) on delete cascade,
  answered int not null check (answered > 0),
  correct int not null check (correct >= 0 and correct <= answered),
  score numeric(5, 2) check (score between 0 and 100),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (attempt_id, competency)
);

create table if not exists public.learning_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  learning_mode text not null default 'Read/Write'
    check (learning_mode in ('Visual', 'Auditory', 'Read/Write', 'Kinesthetic')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.lesson_progress (
  user_id uuid not null references auth.users(id) on delete cascade,
  lesson_id text not null references public.lessons(id) on delete cascade,
  completed boolean not null default false,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);

-- Personal notes a learner writes inside a lesson (Read/Write mode).
create table if not exists public.lesson_notes (
  user_id uuid not null references auth.users(id) on delete cascade,
  lesson_id text not null references public.lessons(id) on delete cascade,
  body text not null default '' check (char_length(body) <= 4000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, lesson_id)
);

-- ---------------------------------------------------------------------
-- 2b. UPGRADE older databases (harmless on a new one): module quizzes and file-based courses
-- ---------------------------------------------------------------------
alter table public.lessons alter column focus_competency drop not null;
alter table public.questions drop constraint if exists questions_kind_check;
alter table public.questions add constraint questions_kind_check check (kind in ('diagnostic', 'lesson', 'module'));
alter table public.assessment_attempts drop constraint if exists assessment_attempts_kind_check;
alter table public.assessment_attempts drop constraint if exists assessment_attempts_check;
alter table public.assessment_attempts drop constraint if exists assessment_attempts_lesson_check;
alter table public.assessment_attempts add constraint assessment_attempts_kind_check check (kind in ('diagnostic', 'lesson', 'module'));
alter table public.assessment_attempts add constraint assessment_attempts_lesson_check
  check ((kind = 'diagnostic' and lesson_id is null) or (kind in ('lesson', 'module') and lesson_id is not null));

-- ---------------------------------------------------------------------
-- 3. INDEXES (foreign keys, and columns used for filters and sorting)
-- ---------------------------------------------------------------------
create index if not exists lessons_course_idx on public.lessons (course_id, position);
create index if not exists questions_lesson_idx on public.questions (lesson_id);
create index if not exists questions_kind_comp_idx on public.questions (kind, competency);
create index if not exists attempts_user_idx on public.assessment_attempts (user_id, created_at desc);
create index if not exists attempts_course_idx on public.assessment_attempts (course_id);
create index if not exists attempts_lesson_idx on public.assessment_attempts (lesson_id);
create index if not exists answers_user_idx on public.assessment_answers (user_id);
create index if not exists answers_question_idx on public.assessment_answers (question_id);
create index if not exists results_user_idx on public.competency_results (user_id);
create index if not exists progress_lesson_idx on public.lesson_progress (lesson_id);
create index if not exists notes_lesson_idx on public.lesson_notes (lesson_id);

