-- ---------------------------------------------------------------------
drop trigger if exists set_updated_at on public.profiles;
create trigger set_updated_at before update on public.profiles for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.courses;
create trigger set_updated_at before update on public.courses for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.lessons;
create trigger set_updated_at before update on public.lessons for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.questions;
create trigger set_updated_at before update on public.questions for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.assessment_attempts;
create trigger set_updated_at before update on public.assessment_attempts for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.assessment_answers;
create trigger set_updated_at before update on public.assessment_answers for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.competency_results;
create trigger set_updated_at before update on public.competency_results for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.learning_preferences;
create trigger set_updated_at before update on public.learning_preferences for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.lesson_progress;
create trigger set_updated_at before update on public.lesson_progress for each row execute function public.set_updated_at();
