-- 6. ROW LEVEL SECURITY: enabled on every table, explicit policy per action
-- No policy is granted to the anon role, so signed-out visitors can read and write nothing.
-- ---------------------------------------------------------------------
alter table public.profiles enable row level security;
alter table public.courses enable row level security;
alter table public.lessons enable row level security;
alter table public.questions enable row level security;
alter table public.assessment_attempts enable row level security;
alter table public.assessment_answers enable row level security;
alter table public.competency_results enable row level security;
alter table public.learning_preferences enable row level security;
alter table public.lesson_progress enable row level security;
alter table public.lesson_notes enable row level security;

-- profiles: read own (admins read all), insert own, update own, no direct delete (cascades from auth.users)
drop policy if exists "profiles select own" on public.profiles;
create policy "profiles select own" on public.profiles for select to authenticated
  using ((select auth.uid()) = id or (select public.is_admin()));
drop policy if exists "profiles insert own" on public.profiles;
create policy "profiles insert own" on public.profiles for insert to authenticated
  with check ((select auth.uid()) = id and role = 'learner');
drop policy if exists "profiles update own" on public.profiles;
create policy "profiles update own" on public.profiles for update to authenticated
  using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

