-- ---------------------------------------------------------------------
-- 7. RPC FUNCTIONS (atomic multi-step actions, run as the caller so RLS still applies)
-- ---------------------------------------------------------------------

-- Saves one assessment attempt, its answers and its per-competency results in ONE transaction.
-- Correctness is recomputed here from questions.correct_index, never trusted from the device.
-- Idempotent: calling it again with the same attempt id updates instead of duplicating.
-- Input: { id, course_id, lesson_id, kind, level, created_at, answers: [{ question_id, selected_index }] }
create or replace function public.sync_attempt(p_attempt jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_id uuid := (p_attempt ->> 'id')::uuid;
begin
  if v_uid is null then
    raise exception 'Not signed in' using errcode = '28000';
  end if;
  if v_id is null then
    raise exception 'Attempt id is required' using errcode = '22023';
  end if;

  insert into public.assessment_attempts (id, user_id, course_id, lesson_id, kind, level, created_at)
  values (
    v_id,
    v_uid,
    p_attempt ->> 'course_id',
    nullif(p_attempt ->> 'lesson_id', ''),
    p_attempt ->> 'kind',
    nullif(p_attempt ->> 'level', ''),
    coalesce((p_attempt ->> 'created_at')::timestamptz, now())
  )
  on conflict (id) do update set level = excluded.level;

  insert into public.assessment_answers (attempt_id, question_id, user_id, selected_index, is_correct)
  select v_id, a.question_id, v_uid, a.selected_index,
         (a.selected_index is not null and a.selected_index = q.correct_index)
  from jsonb_to_recordset(coalesce(p_attempt -> 'answers', '[]'::jsonb))
         as a(question_id text, selected_index smallint)
  join public.questions q on q.id = a.question_id
  on conflict (attempt_id, question_id)
  do update set selected_index = excluded.selected_index, is_correct = excluded.is_correct;

  delete from public.competency_results where attempt_id = v_id;
  insert into public.competency_results (attempt_id, competency, user_id, answered, correct, score)
  select v_id, q.competency, v_uid,
         count(*)::int,
         count(*) filter (where a.is_correct)::int,
         round(100.0 * count(*) filter (where a.is_correct) / count(*), 2)
  from public.assessment_answers a
  join public.questions q on q.id = a.question_id
  where a.attempt_id = v_id and a.selected_index is not null
  group by q.competency;

  update public.assessment_attempts t
  set total_answered = s.answered, total_correct = s.correct
  from (
    select count(*)::int as answered, count(*) filter (where is_correct)::int as correct
    from public.assessment_answers where attempt_id = v_id and selected_index is not null
  ) s
  where t.id = v_id;
end;
$$;
revoke all on function public.sync_attempt(jsonb) from public, anon;
grant execute on function public.sync_attempt(jsonb) to authenticated;

-- Deletes the caller's own attempts, answers, results, lesson progress and notes (Profile > Reset my progress).
create or replace function public.reset_my_progress()
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'Not signed in' using errcode = '28000';
  end if;
  delete from public.assessment_attempts where user_id = v_uid;
  delete from public.lesson_progress where user_id = v_uid;
  delete from public.lesson_notes where user_id = v_uid;
end;
$$;
revoke all on function public.reset_my_progress() from public, anon;
grant execute on function public.reset_my_progress() to authenticated;

-- Admin dashboard data. Runs as the caller: a non-admin only sees their own profile row.
create or replace function public.admin_learner_overview()
returns table (
  user_id uuid,
  display_name text,
  role text,
  joined_at timestamptz,
  attempts bigint,
  lessons_completed bigint,
  last_activity timestamptz
)
language sql
stable
security invoker
set search_path = ''
as $$
  select p.id, p.display_name, p.role, p.created_at,
         (select count(*) from public.assessment_attempts a where a.user_id = p.id),
         (select count(*) from public.lesson_progress lp where lp.user_id = p.id and lp.completed),
         (select max(a.created_at) from public.assessment_attempts a where a.user_id = p.id)
  from public.profiles p
  order by p.created_at desc;
$$;
revoke all on function public.admin_learner_overview() from public, anon;
grant execute on function public.admin_learner_overview() to authenticated;

-- ---------------------------------------------------------------------
-- 8. REALTIME: lets one device learn that another device saved progress
-- ---------------------------------------------------------------------
do $$
declare
  t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['assessment_attempts', 'lesson_progress', 'learning_preferences', 'lesson_notes', 'profiles']
    loop
      begin
        execute format('alter publication supabase_realtime add table public.%I', t);
      exception when duplicate_object then
        null;
      end;
    end loop;
  end if;
end;
$$;

