insert into public.questions (id, lesson_id, kind, competency, difficulty, question_text, options, correct_index, explanation) values
  ('d01', 'basics', 'diagnostic', 0, 1, 'Which of these is hardware?', '["A web browser","A phone screen","A password","A photo editing app"]'::jsonb, 1, 'Hardware is the physical part of a device, such as a screen.'),
