  ('d03', 'basics', 'diagnostic', 0, 2, 'What is a browser used for?', '["Opening and viewing web pages","Charging a phone","Storing a password offline","Printing documents"]'::jsonb, 0, 'A browser retrieves and displays web pages.'),
  ('d04', 'communication', 'diagnostic', 0, 2, 'What is an email attachment?', '["A type of Wi-Fi router","A file sent along with a message","A secret password","A search engine"]'::jsonb, 1, 'An attachment is a file included with an electronic message.'),
  ('d05', 'safety', 'diagnostic', 1, 1, 'Why should each account have its own unique password?', '["It makes the internet faster","It limits the damage if one password leaks","It increases storage","It removes advertisements"]'::jsonb, 1, 'If a password leaks, a unique password protects your other accounts.'),
  ('d06', 'safety', 'diagnostic', 1, 2, 'Why is two-factor authentication useful?', '["It adds a second proof of identity beyond the password","It deletes viruses","It makes your account public","It replaces the internet connection"]'::jsonb, 0, 'A second factor protects the account even if the password is stolen.'),
  ('d07', 'problems', 'diagnostic', 1, 2, 'Why should you test only one troubleshooting change at a time?', '["To make the device slower","To hide the error message","To learn which change fixed the problem","To save battery"]'::jsonb, 2, 'Changing one thing at a time shows what caused the result.'),
  ('d08', 'basics', 'diagnostic', 1, 3, 'Why can data stored in a cloud service be reached from a new phone?', '["It is stored on a remote server, not only on the old phone","The old phone copies itself","All phones share the same storage","Passwords are not needed"]'::jsonb, 0, 'Cloud data lives on remote servers that you can reach after you log in.'),
  ('d09', 'communication', 'diagnostic', 2, 1, 'You need to email an assignment to your teacher. What should you do?', '["Send a blank message","Attach the file and check the recipient address","Share your password","Leave the subject line out"]'::jsonb, 1, 'Add a clear message, attach the file, and check the recipient.'),
  ('d10', 'problems', 'diagnostic', 2, 1, 'A web page will not load. What is a sensible first step?', '["Delete all your files","Check your internet connection","Buy a new device","Share your login details"]'::jsonb, 1, 'Check the simple, reversible things first.'),
  ('d11', 'communication', 'diagnostic', 2, 2, 'Your teacher asks for a PDF named "Unit2". What do you send?', '["A different image","The Unit2 PDF as an attachment","Your login code","An empty email"]'::jsonb, 1, 'Send exactly the requested document as an attachment.'),
  ('d12', 'problems', 'diagnostic', 2, 3, 'An app stops working after you changed three settings at once. What is the best next step?', '["Change three more settings","Undo the changes and re-apply them one at a time","Delete the app and give up","Ask a stranger for your password"]'::jsonb, 1, 'Re-apply changes one at a time to find the cause.'),
  ('d13', 'phishing', 'diagnostic', 3, 1, 'A message says your bank account is blocked and asks for your password now. What should you do?', '["Reply with the password","Tap the link quickly","Check using the official bank app or phone number","Forward the message to friends"]'::jsonb, 2, 'Verify through an official channel you find yourself.'),
  ('d14', 'phishing', 'diagnostic', 3, 2, 'A website looks official but its address is slightly different from the real one. What is safest?', '["Enter your details quickly","Leave and open the official site by typing the address yourself","Download its file","Ignore the browser warning"]'::jsonb, 1, 'A lookalike address is a common sign of impersonation.'),
  ('d15', 'phishing', 'diagnostic', 3, 2, 'A stranger offers a prize if you read out the login code sent to your phone. What should you do?', '["Read out the code","Refuse and report the message","Send your bank details","Open every link they send"]'::jsonb, 1, 'Login codes must never be shared with anyone.'),
  ('d16', 'safety', 'diagnostic', 3, 3, 'Two online posts give opposite safety advice. Which approach is best?', '["Trust whichever is more popular","Compare with official or well-established guidance","Share both without checking","Pick one at random"]'::jsonb, 1, 'Check claims against reliable sources before acting on them.'),
  ('basics-1', 'basics', 'lesson', 0, 1, 'A camera on a phone is an example of which?', '["Software","Hardware","Data","A password"]'::jsonb, 1, 'The camera is a physical component.'),
  ('basics-2', 'basics', 'lesson', 0, 1, 'A saved photo is an example of which?', '["Data","Hardware","A network","A screen"]'::jsonb, 0, 'A photo is information stored on the device.'),
  ('basics-3', 'basics', 'lesson', 0, 2, 'Which pair correctly matches hardware and software?', '["Screen and battery","Keyboard and messaging app","Browser and calculator app","Photo and video"]'::jsonb, 1, 'A keyboard is hardware and a messaging app is software.'),
  ('basics-4', 'basics', 'lesson', 0, 2, 'An application is best described as:', '["A physical part of a device","Software built for a specific task","A kind of cable","A secret code"]'::jsonb, 1, 'Applications are task-specific software.'),
  ('basics-5', 'basics', 'lesson', 0, 3, 'A notes app saves only on your phone. What is a main risk?', '["Notes are lost if the phone is lost or broken","The app becomes hardware","Notes cannot be typed","The screen turns off"]'::jsonb, 0, 'Local-only data has no backup copy elsewhere.'),
  ('basics-6', 'basics', 'lesson', 0, 3, 'Why can a cloud-synced app work on a new phone after login?', '["The data is stored on a remote server","The new phone is the same hardware","Software cannot move","Passwords are copied by Wi-Fi"]'::jsonb, 0, 'Cloud data is kept on a server and linked to your account.'),
  ('safety-1', 'safety', 'lesson', 1, 1, 'Which is the safest thing to do with your password?', '["Share it with a friend","Keep it private","Write it in a public chat","Use your name"]'::jsonb, 1, 'A password is a secret and should stay private.'),
  ('safety-2', 'safety', 'lesson', 1, 1, 'What does the internet do?', '["Connects devices around the world","Charges phones","Makes screens brighter","Stores only photos"]'::jsonb, 0, 'The internet connects networks and devices.'),
  ('safety-3', 'safety', 'lesson', 1, 2, 'Why is a long password with four unrelated words a good choice?', '["It is hard to guess","It is the same everywhere","It is short","It works without internet"]'::jsonb, 0, 'Length and unpredictability make guessing harder.'),
  ('safety-4', 'safety', 'lesson', 1, 2, 'What does two-factor authentication add?', '["A second proof of identity","Faster internet","More storage","A new keyboard"]'::jsonb, 0, 'It requires something beyond the password.'),
  ('safety-5', 'safety', 'lesson', 1, 3, 'A shop leaks your password, which you reused on email. What is the most likely result?', '["Nothing happens","An attacker may try it on your email account","Your phone updates","Your Wi-Fi slows"]'::jsonb, 1, 'Attackers reuse leaked passwords on other sites.'),
  ('safety-6', 'safety', 'lesson', 1, 3, 'A flashlight app asks for contacts and location. What does this suggest?', '["It needs them to shine light","It requests more data than its purpose needs","It is safer","It is a browser"]'::jsonb, 1, 'Permissions should match the purpose of the app.'),
  ('phishing-1', 'phishing', 'lesson', 3, 1, 'A message says "Act now or lose your account!" What should you do?', '["Tap the link","Stop and verify it another way","Reply with your password","Forward it"]'::jsonb, 1, 'Urgency is a warning sign. Verify separately.'),
  ('phishing-2', 'phishing', 'lesson', 3, 1, 'What is phishing?', '["A fake message trying to steal your information","A way to charge a phone","A kind of keyboard","A video format"]'::jsonb, 0, 'Phishing impersonates a trusted sender to steal information.'),
  ('phishing-3', 'phishing', 'lesson', 3, 2, 'Which is the best way to check a message that claims to be from your bank?', '["Tap the link in the message","Open the bank app yourself or call the official number","Reply asking if it is real","Wait a week"]'::jsonb, 1, 'Use an official channel you find yourself.'),
  ('phishing-4', 'phishing', 'lesson', 3, 2, 'Which is a common warning sign in a link?', '["An address that only resembles the real one","A padlock on every page","A short message","A blue button"]'::jsonb, 0, 'Lookalike addresses imitate real sites.'),
  ('phishing-5', 'phishing', 'lesson', 3, 3, 'A message uses your real name and school but asks you to log in via a shortened link. What is the best conclusion?', '["It must be genuine because it knows you","Personal details do not prove it is genuine, so verify out of band","Ignore the link but share your code","Reply with a photo of your ID"]'::jsonb, 1, 'Attackers can gather personal details.'),
