  ('nb1-01', 'nb-m1', 'module', 0, 1, 'What is a computer network?', '["A set of connected devices that exchange data","A computer with extra storage","Only a website","A single disconnected phone"]'::jsonb, 0, 'A network allows connected devices to exchange data and share resources.'),
  ('nb1-02', 'nb-m1', 'module', 0, 1, 'What does LAN stand for?', '["Large Access Node","Local Area Network","Linked Application Network","Long Area Navigation"]'::jsonb, 1, 'LAN means Local Area Network.'),
  ('nb1-03', 'nb-m1', 'module', 0, 1, 'Which example is typically a WAN?', '["Devices in one classroom","Keyboard attached to a laptop","Network connecting offices in different cities","A printer connected by USB only"]'::jsonb, 2, 'A WAN connects networks across broader geographic areas.'),
  ('nb1-04', 'nb-m1', 'module', 1, 2, 'Why can a printer work on a LAN without internet?', '["Printers always contain mobile data","The internet is stored in the printer","Wi-Fi automatically creates an internet service","A LAN can carry local traffic independently"]'::jsonb, 3, 'Local devices can communicate without a connection to the global internet.'),
  ('nb1-05', 'nb-m1', 'module', 1, 2, 'How does the internet differ from a LAN?', '["The internet interconnects many networks globally","The internet is a single computer","A LAN always uses cables","A LAN cannot transfer files"]'::jsonb, 0, 'The internet connects many separate networks; a LAN covers a limited area.'),
  ('nb1-06', 'nb-m1', 'module', 1, 2, 'Why can a phone show Wi-Fi connected but a website fail?', '["Wi-Fi and internet are identical","Wi-Fi may connect locally while internet access is down","The phone has no screen","All websites require Ethernet"]'::jsonb, 1, 'Wi-Fi connectivity does not guarantee an upstream internet connection.'),
  ('nb1-07', 'nb-m1', 'module', 2, 2, 'Two laptops need to exchange a file in the same room without internet. What is suitable?', '["Wait until a search engine loads","Buy a domain name","Use a local network or direct local sharing","Use only a WAN subscription"]'::jsonb, 2, 'Local file sharing can operate without internet.'),
  ('nb1-08', 'nb-m1', 'module', 2, 2, 'A school wants computers in one lab to share a printer. Which network fits?', '["WAN across provinces","Satellite-only global network","No network at all","LAN in the computer lab"]'::jsonb, 3, 'A LAN is appropriate for a limited location.'),
  ('nb1-09', 'nb-m1', 'module', 2, 2, 'A learner needs to open an online article hosted abroad. What is generally required?', '["An internet connection","Only a powered printer","Only Bluetooth headphones","A USB mouse"]'::jsonb, 0, 'Accessing a remote public website generally requires internet connectivity.'),
  ('nb1-10', 'nb-m1', 'module', 3, 3, 'An office has a functioning LAN, but external websites fail on every computer. Which explanation is most plausible?', '["All local network links must be broken","The upstream internet connection or gateway may be unavailable","Every computer is infected","The office has too many printers"]'::jsonb, 1, 'The LAN may still work while its internet connection fails.'),
  ('nb1-11', 'nb-m1', 'module', 3, 3, 'Which setup best supports local file sharing during an internet outage?', '["Devices depending exclusively on a cloud-only server","Devices with networking disabled","Devices on the same working LAN with a local file server","Devices with no local storage or connection"]'::jsonb, 2, 'A local server and LAN can remain available during an outside outage.'),
